    keywordsList: [{ word: "academy", translation: "академия" }, { word: "ancient", translation: "древний, старинный" }, { word: "board", translation: "доска" }, { word: "century", translation: "век, столетие" }, { word: "clue", translation: "улики, зацепки" }, { word: "concert", translation: "концерт" }, { word: "county", translation: "округ" }, { word: "dictionary", translation: "словарь" }, { word: "exist", translation: "существовать" }, { word: "flat", translation: "плоский, ровный" }, { word: "gentleman", translation: "джентльмен" }, { word: "hidden", translation: "скрытый, спрятанный" }, { word: "maybe", translation: "может быть, возможно" }, { word: "officer", translation: "офицер" }, { word: "original", translation: "оригинальный, подлинный" }, { word: "pound", translation: "стучать, бить" }, { word: "process", translation: "процесс" }, { word: "publish", translation: "опубликовать" }, { word: "theater", translation: "театр" }, { word: "wealth", translation: "богатство" }],
